	@Test
	void configurationReplacementCannotShutDownAnActiveRequest() throws Exception {
		RepositoryManager manager = mock(RepositoryManager.class);
		when(manager.getRepository("source")).thenReturn(mock(Repository.class));
		when(manager.hasRepositoryConfig("source")).thenReturn(true);
		RepositoryInterceptor reader = interceptor(manager);
		RepositoryInterceptor writer = interceptor(manager);
		HttpServletRequest read = request("GET", "/source/size");
		HttpServletRequest update = request("PUT", "/source/config");
		HttpServletResponse response = mock(HttpServletResponse.class);
		reader.preHandle(read, response, null);
		try {
			assertThrows(ClientHTTPException.class, () -> writer.preHandle(update, response, null));
		} finally {
			reader.afterCompletion(read, response, null, null);
		}
	}

